                    _hook_plan_data["overlay_start_s"] = _hook_visual_metadata["hook_visual_start"]
                    _hook_plan_data["overlay_duration_s"] = _hook_visual_metadata["hook_visual_duration"]
                    _hook_plan_data["overlay_warnings"] = []
